// Des: Open a chat by name or phone: scroll, search
// Flo: parse target (#group, #person) > candidates (DOM rows or AX nodes) > exact name match > scroll > search > pick or Ambiguous/NoElem > click
// I/O: Sess + name text (caller) > Opened (canonical name, stranger flag); chat open on the page
// ===================================================================
const std = @import("std"); const sess = @import("ru-sess-ctxz.zig"); const rd = @import("ru-chat-read.zig"); const extr = @import("ru-page-extr.zig"); const scrl = @import("ru-page-scrl.zig"); const inpu = @import("ru-huma-inpu.zig"); const snap = @import("ru-page-snap.zig");
pub const Qual = enum { any, group, person };
pub const Target = struct { name: []const u8, qual: Qual };
pub const Pick = struct { name: []const u8, stran: bool, group: bool, node: ?snap.Node, x: f64, y: f64, srch: bool = false, idx: u32 = 0 };
pub const Opened = struct { name: []const u8, stran: bool };
pub fn parseTarget(raw: []const u8) Target { const trm = std.mem.trim(u8, raw, " "); if (std.mem.lastIndexOfScalar(u8, trm, '#')) |idx| { const tail = trm[idx + 1 ..]; if (std.ascii.eqlIgnoreCase(tail, "group")) return .{ .name = std.mem.trim(u8, trm[0..idx], " "), .qual = .group }; if (std.ascii.eqlIgnoreCase(tail, "person")) return .{ .name = std.mem.trim(u8, trm[0..idx], " "), .qual = .person }; } return .{ .name = trm, .qual = .any }; }
fn cands(ses: *sess.Sess) ![]Pick { var out: std.ArrayList(Pick) = .empty; if (ses.reg.ext.chat_sel.len > 0) { const rows = try extr.chatsDom(ses.aren, ses.conn, ses.reg.ext); for (rows) |row| try out.append(ses.aren, .{ .name = rd.chatName(&ses.reg, row.name), .stran = row.stran, .group = row.group, .node = null, .x = row.x, .y = row.y, .idx = row.idx }); return out.items; } const chats = try rd.listChats(ses); for (chats) |cht| try out.append(ses.aren, .{ .name = cht.name, .stran = cht.stran, .group = false, .node = cht.node, .x = 0, .y = 0 }); return out.items; }
fn squz(aren: std.mem.Allocator, txt: []const u8) []const u8 { var out: std.ArrayList(u8) = .empty; var idx: usize = 0; while (idx < txt.len) : (idx += 1) { if (txt[idx] == 0xC2 and idx + 1 < txt.len and txt[idx + 1] == 0xA0) { idx += 1; continue; } if (txt[idx] != ' ') out.append(aren, std.ascii.toLower(txt[idx])) catch return txt; } return out.items; }
pub fn looseHit(name: []const u8, want: []const u8) bool { var buf: [512]u8 = undefined; var fba = std.heap.FixedBufferAllocator.init(&buf); const aa = squz(fba.allocator(), name); const bb = squz(fba.allocator(), want); return bb.len >= 5 and std.mem.find(u8, aa, bb) != null; }
fn matchOne(ses: *sess.Sess, tgt: Target) !?Pick { const all = try cands(ses); var found: ?Pick = null; var hits: u32 = 0; for (all) |pck| { if (!std.ascii.eqlIgnoreCase(pck.name, tgt.name) and !looseHit(pck.name, tgt.name)) continue; if (tgt.qual == .group and !pck.group) continue; if (tgt.qual == .person and pck.group) continue; hits += 1; if (found == null) found = pck; } if (hits > 1) { const note = try std.fmt.allocPrint(ses.aren, "ambiguous chat name: {s} ({d} matches)", .{ tgt.name, hits }); ses.logz("warn", note); return error.Ambiguous; } return found; }
pub fn isPhone(txt: []const u8) bool { if (txt.len < 8) return false; for (txt) |chr| { if (!std.ascii.isDigit(chr)) return false; } return true; }
fn focusSearch(ses: *sess.Sess) !void { if (ses.reg.ext.sear_sel.len > 0) { const pnt = (try extr.revealNth(ses.aren, ses.conn, ses.reg.ext.sear_sel, 0)) orelse return error.NoElem; ses.pos = try inpu.clickAt(ses.aren, ses.conn, ses.hum(), ses.pos, pnt); return; } const box = try ses.findKey("sear_boxz"); try ses.clickNode(box); }
fn clearSearch(ses: *sess.Sess) !void { try focusSearch(ses); try inpu.clearField(ses.aren, ses.conn); }
pub fn locate(ses: *sess.Sess, raw: []const u8) !Pick { const tgt = parseTarget(raw); if (tgt.name.len == 0) return error.BadJob; if (try matchOne(ses, tgt)) |pck| return pck; var step: u32 = 0; while (step < ses.cfg.scrl_step_maxz) : (step += 1) { if (!try scrl.listDown(ses)) break; ses.readPause(); if (try matchOne(ses, tgt)) |pck| return pck; } try scrl.listUp(ses, 2); try focusSearch(ses); try inpu.clearField(ses.aren, ses.conn); try ses.typeIn(tgt.name); ses.readPause(); if (isPhone(tgt.name)) { const all = try cands(ses); if (all.len == 1) { var sp = all[0]; sp.srch = true; return sp; } if (all.len > 1) return error.Ambiguous; } if (try matchOne(ses, tgt)) |pck| { var sp = pck; sp.srch = true; return sp; } try clearSearch(ses); const note = try std.fmt.allocPrint(ses.aren, "chat not found: {s}", .{tgt.name}); ses.logz("warn", note); return error.NoElem; }
pub fn openChat(ses: *sess.Sess, raw: []const u8) !Opened { const pck = try locate(ses, raw); if (pck.stran and ses.mode != .force) { if (pck.srch) try clearSearch(ses); return error.NeedForce; } if (pck.node) |nod| { try ses.clickNode(nod); } else { const pnt = (try extr.revealNth(ses.aren, ses.conn, ses.reg.ext.chat_sel, pck.idx)) orelse inpu.Pt{ .x = pck.x, .y = pck.y }; ses.pos = try inpu.clickAt(ses.aren, ses.conn, ses.hum(), ses.pos, pnt); } ses.readPause(); if (pck.srch) try clearSearch(ses); return .{ .name = pck.name, .stran = pck.stran }; }
